// Capturar os dados de forma segura, com verificações
try {
  // Obter o post do LinkedIn
  let linkedinPost = "";
  if ($node["Generate LinkedIn Post"] && $node["Generate LinkedIn Post"].json) {
    linkedinPost = $node["Generate LinkedIn Post"].json.output || "";
  }

  // Obter a URL da imagem
  let imageUrl = "";
  if ($input.first() && $input.first().json && $input.first().json.data && 
      $input.first().json.data[0] && $input.first().json.data[0].url) {
    imageUrl = $input.first().json.data[0].url;
  }

  // Obter os dados do formulário
  let palavraChave = "";
  let publicoAlvo = "";
  if ($node["On form submission"] && $node["On form submission"].json) {
    palavraChave = $node["On form submission"].json["Palavra-chave"] || "";
    publicoAlvo = $node["On form submission"].json["Público-alvo"] || "";
  }

  // Retornar objeto com todos os dados necessários
  return {
    json: {
      linkedinPost: linkedinPost,
      imageUrl: imageUrl,
      palavra_chave: palavraChave,
      publico_alvo: publicoAlvo
    }
  };
} catch (error) {
  // Se ocorrer qualquer erro, retornar um objeto com valores default
  console.log("Erro ao preparar post do LinkedIn:", error);
  return {
    json: {
      linkedinPost: "Post padrão sobre agentes de IA para empresas",
      imageUrl: "",
      palavra_chave: "Agentes de IA",
      publico_alvo: "Empresários"
    }
  };
}

